pub(crate) fn run(graph: &Graph, q: &SearchQuery) -> Result<SearchResult, GraphError> {
    let query = q.query.trim();
    let limit = q.limit();
    // Either would return an empty result that looks like "no matches"
    // (STD-01 §R29).
    if query.is_empty() {
        return Err(GraphError::invalid_input(
            "validate graph search",
            "query",
            "the search query must not be empty",
        ));
    }
    if limit == 0 {
        return Err(GraphError::invalid_input(
            "validate graph search",
            "limit",
            "the search limit must be at least 1",
        ));
    }

    // One match past the limit shows whether more exist without counting
    // them all.
    let mut raw_matches = graph
        .with_read_connection(|conn| query_matches(conn, q, query, limit.saturating_add(1)))?;
    let truncated = raw_matches.len() > limit;
    raw_matches.truncate(limit);
    let matches = raw_matches
        .into_iter()
        .map(|raw| materialize_match(graph, raw))
        .collect::<Result<Vec<_>, _>>()?;
    Ok(SearchResult {
        total: (!truncated).then_some(matches.len()),
        matches,
        truncated,
    })
}

fn materialize_match(graph: &Graph, raw: RawMatch) -> Result<Match, GraphError> {
    let line = match (raw.line, raw.span_start) {
        (Some(line), _) => i64_to_usize("convert graph search line", line)?,
        (None, Some(span_start)) => symbol_line(graph, raw.path.as_str(), span_start)?,
        (None, None) => {
            return Err(GraphError::invalid_data(
                "materialize graph search match",
                "match row has neither line nor span_start",
            ));
        }
    };

    Ok(match raw.kind {
        SearchKind::Symbol => Match::Symbol {
            name: raw.label,
            path: raw.path,
            line,
        },
        SearchKind::String => Match::StringLiteral {
            value: raw.label,
            path: raw.path,
            line,
        },
        SearchKind::Config => Match::Config {
            value: raw.label,
            path: raw.path,
            line,
        },
    })
}

