pub(super) fn interrupted_writes(corpus: &Corpus, r: &mut Report) {
    let root = corpus.root();
    // Relative to the root, in the order they are reported.
    let mut debris: Vec<PathBuf> = Vec::new();
    for dir in ["nodes", "inbox"] {
        let path = root.join(dir);
        match temporaries(&path) {
            Ok(found) => debris.extend(found.into_iter().map(|name| Path::new(dir).join(name))),
            Err(error) => r.push(
                Severity::Error,
                Rule::InterruptedWrite,
                None,
                format!(
                    "could not inspect temporary files in {}: {error}",
                    path.display()
                ),
            ),
        }
    }
    let beside_root_files = |name: &OsString| {
        let name = name.to_string_lossy();
        [config::FILE, GITIGNORE_FILE, PENDING_FILE]
            .iter()
            .any(|file| name.starts_with(&format!("{file}.")))
    };
    match temporaries(root) {
        Ok(found) => debris.extend(
            found
                .into_iter()
                .filter(beside_root_files)
                .map(PathBuf::from),
        ),
        Err(error) => r.push(
            Severity::Error,
            Rule::InterruptedWrite,
            None,
            format!(
                "could not inspect temporary files in {}: {error}",
                root.display()
            ),
        ),
    }
    for relative in debris {
        r.push(
            Severity::Warn,
            Rule::InterruptedWrite,
            None,
            format!(
                "`{}` is a temporary file left by a write that did not finish; nothing reads \
                 or commits it, and nebula never deletes it. Once it holds nothing you need, \
                 remove it: rm {}",
                relative.display(),
                shell_quote(&root.join(&relative).display().to_string())
            ),
        );
    }

/// The names in `dir` that end `.tmp`, sorted. None when `dir` is not there.
fn temporaries(dir: &Path) -> Result<Vec<OsString>> {
    let entries = match std::fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(error) => return Err(Error::io_at("reading", dir, error)),
    };
    let mut names = Vec::new();
    for entry in entries {
        let name = entry
            .map_err(|error| Error::io_at("reading", dir, error))?
            .file_name();
        if name.to_string_lossy().ends_with(".tmp") {
            names.push(name);
        }
    }
    names.sort();
    Ok(names)
}

    // This is a diagnostic scan, not recovery: isolate every failure of
    // this record so unrelated findings survive (STD-02 §R32).
    if let Err(error) = pending_write(corpus, r) {
        r.push(
            Severity::Error,
            Rule::InterruptedWrite,
            None,
            format!(
                "could not inspect unfinished write recorded in {}: {error}",
                pending::pending_path(root).display()
            ),
        );
    }
}

fn pending_write(corpus: &Corpus, r: &mut Report) -> Result<()> {
    let root = corpus.root();
    let record = pending::pending_path(root);
    match pending::read(root) {
        Ok(None) => {}
        Ok(Some(PendingWrite::Promote { entry, node, .. })) => {
            let outcome = if corpus.node_path(&node)?.exists() {
                format!("`{node}` was written, so the next write strikes the entry `-> {node}`")
            } else {
                format!("`{node}` was never written, so the next write leaves the entry waiting")
            };
            r.push(
                Severity::Warn,
                Rule::InterruptedWrite,
                None,
                format!(
                    "a promotion of inbox entry `{entry}` did not finish, as {} records; \
                     {outcome}",
                    record.display()
                ),
            );
        }
        Err(Error::PendingWriteUnreadable { path, reason }) => r.push(
            Severity::Error,
            Rule::InterruptedWrite,
            None,
            format!(
                "{} records an unfinished write that this build cannot read ({reason}); every \
                 write refuses until it has been read by hand and removed: rm {}",
                path.display(),
                shell_quote(&path.display().to_string())
            ),
        ),
        Err(error) => return Err(error),
    }
    Ok(())
}

def read_holder(fd: int) -> dict[str, Any] | None:
    """The last holder record in the lock file, or None if there is none (or it is garbage).

    It may be stale: the holder writes it just after acquiring, so a waiter
    can briefly read the previous holder's record.
    """
    try:
        raw = os.pread(fd, _HOLDER_MAX_BYTES, 0)
        record = as_object(json.loads(raw))
    except (OSError, ValueError):
        return None
    if record is None:
        return None
    return {k: record[k] for k in ("pid", "label", "acquired_at") if k in record}

def as_object(value: object) -> JSONObject | None:
    """``value`` as a JSON object, or None when it is anything else."""
    return cast(JSONObject, value) if isinstance(value, dict) else None

def _create_key(self) -> Fernet:
    """Create the key exactly once, even with several processes racing.

    ``publish_new_private`` never exposes a half-written key and fails if
    the name exists; the loser reads the winner's key, so two processes
    can never encrypt under different keys.
    """
    with contextlib.suppress(FileExistsError):
        publish_new_private(self.paths.key_file, Fernet.generate_key())
    require_private(self.paths.key_file)
    return self._read_key()

def _fernet(self, create: bool) -> Fernet:
    try:
        return self._read_key()
    except FileNotFoundError:
        if not create:
            raise
    return self._create_key()

