pub(crate) fn acquire_observation_lock(
    db_path: &Path,
    timeout: std::time::Duration,
) -> Result<FileLockGuard, GraphError> {
    let parent = db_path.parent().ok_or_else(|| {
        GraphError::invalid_data(
